   686  /* Apply transparency to truecolor output row */
   687  static inline void trns_row(unsigned char *row,
   688                                unsigned char *scanline,
   689                                unsigned char *trns,
   690                                uint32_t pixels,
   691                                int fmt,
   692                                unsigned ctype,
   693                                unsigned depth)
   694  {
   695      if(ctype != SPNG_COLOR_TYPE_TRUECOLOR) return;
   696
   697      uint32_t i;
   698      unsigned scanline_stride = 3; /* depth == 8 */
   699      if(depth == 16) scanline_stride = 6;
   700
   701      if(fmt == SPNG_FMT_RGBA8)
   702      {
   703          for(i=0; i < pixels; i++, scanline+=scanline_stride, row+=4)
   704          {
   705              if(!memcmp(scanline, trns, scanline_stride)) row[3] = 0;
   706          }
   707      }
   708      else if(fmt == SPNG_FMT_RGBA16)
   709      {
   710          for(i=0; i < pixels; i++, scanline+=scanline_stride, row+=8)
   711          {
   712              if(!memcmp(scanline, trns, scanline_stride)) memset(row+6, 0, 2);
   713          }
   714      }
   715  }
